<script setup>
import { reactive,watch,computed,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { studio,roles,getRole } from '../store.js';import Icon from '../components/Icon.vue';
const route=useRoute(),router=useRouter(),error=ref('');const initial=getRole(route.query.role)||getRole(studio.state.value.preparation?.roleId)||getRole(studio.state.value.preference)||roles[0];
const form=reactive({roleId:initial.id,level:'校招',mode:'coaching',questionCount:4,resumeMode:'sample',resume:initial.resume,jd:initial.jd,...(!route.query.role||studio.state.value.preparation?.roleId===route.query.role?studio.state.value.preparation||{}:{})});const role=computed(()=>getRole(form.roleId));
function choose(item){form.roleId=item.id;form.jd=item.jd;form.resume=item.resume;form.resumeMode='sample'}
watch(form,()=>studio.call('savePreparation',{...form}),{deep:true});function create(){try{const s=studio.call('createSession',{...form});router.push(`/interviews/${s.id}/plan`)}catch(e){error.value=e.message}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">01 / PREPARE</p><h1>先做好准备，再从容开场。</h1><p class="muted">岗位、目标和经历，组成这次练习的起点。</p></div></div><form @submit.prevent="create" class="prepare-grid"><div class="stack"><section class="card"><h2>选择你的目标岗位</h2><div class="role-grid compact"><button type="button" v-for="item in roles" :key="item.id" class="role-card" :class="{selected:form.roleId===item.id}" @click="choose(item)"><Icon :name="item.icon"/><strong>{{item.title}}</strong><small>{{item.skills.join(' · ')}}</small></button></div><div class="form-row"><label>求职阶段<select v-model="form.level"><option>校招</option><option>初级</option><option>中级</option></select></label><label>练习长度<select v-model="form.questionCount"><option :value="2">轻量练习 · 2 道主问题</option><option :value="4">完整练习 · 4 道主问题</option></select></label></div><label>练习模式<select v-model="form.mode"><option value="coaching">陪练模式 · 回答后即时反馈</option><option value="simulation">模拟模式 · 结束后统一反馈</option></select></label></section><section class="card"><h2>带上你的项目经历</h2><label>经历来源<select v-model="form.resumeMode"><option value="sample">使用岗位示例</option><option value="paste">粘贴自己的经历</option><option value="skip">暂不提供</option></select></label><label v-if="form.resumeMode!=='skip'">项目经历<textarea v-model="form.resume" rows="5" maxlength="12000" :readonly="form.resumeMode==='sample'" placeholder="项目背景、个人职责、技术方案与结果"/></label><p class="muted small">内容仅保存于本机。当前面试仍为 Mock；真实文件可先上传、解析并确认入库。</p><RouterLink to="/resumes/real" class="text-link">上传与确认真实简历 →</RouterLink><label>目标岗位要求（JD）<textarea v-model="form.jd" rows="4" maxlength="12000" required/></label></section></div><aside class="card preparation-summary"><span class="badge">DEMO</span><h2>{{role.title}}</h2><p>{{role.tagline}}</p><div class="tags"><span v-for="skill in role.skills" :key="skill">{{skill}}</span></div><hr><h3>这次你将获得</h3><ul class="plain-list"><li>一份清晰的面试方案</li><li>岗位题目与一次定向追问</li><li>逐题复盘与专项练习</li><li>可回看的历史与成长记录</li></ul><p class="notice">演示版使用固定岗位题库与关键词规则。阶段、JD 和经历会保存到方案，但不会调用 AI 动态生成题目。</p><p v-if="error" role="alert" class="error">{{error}}</p><button class="button primary wide" type="submit">生成面试方案 <Icon name="right"/></button></aside></form></template>
